#!/usr/bin/env python3
"""Read ids.txt (one order id per line, most recent last) and print the next id."""

import sys

BASE36 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
PREFIX = 'ORD-'
SUFFIX_LEN = 4


def to_base36(n: int, width: int) -> str:
    """Format an integer as a zero-padded base-36 string of the given width."""
    chars = []
    for _ in range(width):
        chars.append(BASE36[n % 36])
        n //= 36
    return ''.join(reversed(chars))


def next_id(path='ids.txt') -> str:
    with open(path) as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        return PREFIX + '0' * SUFFIX_LEN

    last = lines[-1]
    suffix = last[len(PREFIX):]
    n = int(suffix, 36) + 1
    return PREFIX + to_base36(n, SUFFIX_LEN)


if __name__ == '__main__':
    print(next_id())

