#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate events by event_id, write deduped.jsonl."""

import json


def main():
    seen = set()
    with open("events.jsonl") as infile, open("deduped.jsonl", "w") as outfile:
        for line in infile:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid is None:
                outfile.write(line + "\n")
                continue
            if eid not in seen:
                seen.add(eid)
                outfile.write(line + "\n")


if __name__ == "__main__":
    main()

