#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path(__file__).resolve().parent / "release"
MANIFEST_PATH = Path(__file__).resolve().parent / "manifest.json"


def sha256_digest(filepath: Path) -> str:
    return hashlib.sha256(filepath.read_bytes()).hexdigest()


def build_manifest() -> dict[str, str]:
    manifest: dict[str, str] = {}
    release_path = RELEASE_DIR.resolve()

    for fpath in sorted(release_path.rglob("*")):
        if not fpath.is_file():
            continue
        # Store the path relative to the repo root
        rel = fpath.relative_to(release_path.parent)
        manifest[str(rel)] = sha256_digest(fpath)

    return manifest


def main() -> None:
    manifest = build_manifest()
    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n")
    print(f"Wrote {MANIFEST_PATH} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

