import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST_FILE = "manifest.json"


def sha256_digest(filepath: str) -> str:
    """Return the hex SHA-256 digest of the given file."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    for root, _dirs, files in os.walk(RELEASE_DIR):
        for filename in files:
            full_path = os.path.join(root, filename)
            rel_path = os.path.normpath(full_path).replace(os.sep, "/")
            manifest[rel_path] = sha256_digest(full_path)

    with open(MANIFEST_FILE, "w") as f:
        json.dump(manifest, f, indent=2)

    print(f"Wrote {MANIFEST_FILE} with {len(manifest)} entries.")


if __name__ == "__main__":
