#!/usr/bin/env python3
"""Print the file names under reports/, one per line, in report order."""

import os
import re

REPORTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reports")


def report_sort_key(name: str) -> tuple:
    """Extract numeric sequence from a report filename for natural sorting."""
    match = re.search(r"(\d+)", name)
    return (int(match.group(1)),) if match else (0,)


def main() -> None:
    try:
        files = [f for f in os.listdir(REPORTS_DIR) if os.path.isfile(os.path.join(REPORTS_DIR, f))]
    except FileNotFoundError:
        print("error: reports/ directory not found", file=__import__("sys").stderr)
        __import__("sys").exit(1)

    files.sort(key=report_sort_key)

    for f in files:
        print(f)


if __name__ == "__main__":
    main()

