#!/usr/bin/env python3
"""List report files in reports/ in report order (report-1, report-2, ...)."""

import re
from pathlib import Path


REPORTS_DIR = Path(__file__).resolve().parent / "reports"
REPORT_PATTERN = re.compile(r"^report-(\d+)\.txt$")


def main() -> None:
    if not REPORTS_DIR.is_dir():
        return

    entries = []
    for child in REPORTS_DIR.iterdir():
        m = REPORT_PATTERN.match(child.name)
        if m:
            entries.append((int(m.group(1)), child.name))

    entries.sort(key=lambda x: x[0])
    for _, name in entries:
        print(name)


if __name__ == "__main__":
    main()

