"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
from datetime import datetime, timezone


def parse_timestamp(line: str) -> datetime | None:
    """Parse the leading YYYY-MM-DD HH:MM:SS timestamp from a log line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("Error: AS_OF must be an integer Unix timestamp.", file=sys.stderr)
        sys.exit(1)

    threshold = as_of - 7 * 86400  # strictly older than 7 days before AS_OF

    log_path = "app.log"
    archive_path = "archive.log"

    try:
        with open(log_path) as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"Error: {log_path} not found.", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        if not line.strip():
            keep.append(line)
            continue

        ts = parse_timestamp(line)
        if ts is None:
            keep.append(line)
            continue

        entry_ts = ts.timestamp()
        if entry_ts < threshold:
            archive.append(line)
        else:
            keep.append(line)

    # Write archive.log (append mode to preserve existing content)
    if archive:
        with open(archive_path, "a") as f:
            for line in archive:
                f.write(line)

    # Rewrite app.log with remaining entries
    with open(log_path, "w") as f:
        for line in keep:
            f.write(line)


if __name__ == "__main__":
    main()
